mapper.select:
SELECT fpa.*, ( SELECT su.DESCRIPTION FROM sys_user su WHERE su.USER_ID = fpa.upload_person ) AS upload_person_name, ( select sf.file_id from sys_attachment sa, sys_file sf
fpa.project_attachment_id||''= sa.source_key
AND sa.source_type = #{sourceType}
AND sa.attachment_id = sf.attachment_id and rownum=1
) file_id, ( SELECT hdft.templet_name FROM hls_doc_file_templet hdft WHERE hdft.templet_id = fpa.template_id ) AS template_id_n, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=fpa.bp_id) as bp_id_n, fpa.signing_witness as signing_witness_name, fpa.witness as witness_name, fpa.SYSTEM_NUMBER, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scvb.value=fpa.SOURCE_TYPE and scb.code='CON.CONTENT_NUM_TYPE' and scvb.code_id=scb.code_id ) as SOURCE_TYPE_N FROM fct_project_attachment fpa
1=1
and fpa.project_id = #{projectId}
and fpa.source_type = #{sourceType}
and fpa.status = #{status}
and fpa.bp_category not in ('PRJ_CONTRACT_CONTENT_WFL','FCT_CONTRACT_CONTENT_WFL','PRJ_CONTRACT_CONTENT_ATT','FCT_CONTRACT_CONTENT_ATT','CUSTOM_FCT_CONTRACT','CUSTOM_CON_CONTRACT')
order by fpa.creation_date ASC

select * from ( select ttt.*, @rownum := @rownum + 1 con_seq from (SELECT
fpa.major_con_flag, fpa.content_flag, CASE
WHEN fpa.content_flag = 'Y' THEN '已生成' ELSE '未生成' END AS content_flag_n, fpa.UNDERWRITE_DESCRIPTION, fpa.SIGN_DATE, fpa.SIGN_PLACE, fpa.SIGN_DESCRIPTION, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'SYS.YES_NO' AND scb.CODE_ID = scv.CODE_ID AND scv. VALUE = fpa.major_con_flag ) AS major_con_flag_n, fpa.project_attachment_id, fpa.project_id, fpa.source_type, fpa.source_id, fpa.bp_category, fpa.bp_id, ( SELECT tt.bp_name FROM hls_bp_master tt WHERE tt.bp_id = fpa.bp_id ) AS bp_id_n, fpa.CON_CONTENT_AMOUNT, fpa.document_number, fpa.document_name, fpa.description, fpa.STATUS, fpa.template_id, fpa.content_sign_date, fpa.content_sign_location, fpa.signing_witness, fpa.witness, fpa.witness_bank, fpa.witness_location, fpa.is_final_print, fpa.stamp_name, fpa.company_seal, fpa.rep_seal, fpa.copies, fpa.print_comment, fpa.object_version_number, fpa.request_id, fpa.program_id, fpa.created_by, fpa.creation_date, fpa.last_updated_by, fpa.last_update_date, fpa.last_update_login, fpa.standard_contract, fpa.bp_role_type, ( SELECT tt.DESCRIPTION FROM hls_bp_type tt WHERE tt.BP_TYPE = fpa.bp_role_type ) AS bp_role_type_n, fpa.inter_status, fpa.inter_info, fpa.system_number, fpa.prj_notice_id, (CASE WHEN fpa.source_type IN ( 'MORTGAGE_CONTRACT', 'CONTRACT_OF_PLEDGE' ) THEN ( SELECT hli.full_name FROM hls_lease_item hli WHERE hli.lease_item_id = fpa.source_id ) WHEN fpa.source_type = 'DEPOSIT_CONTENT' THEN ( SELECT h.bp_name FROM hls_bp_master h WHERE h.bp_id = fpa.source_id ) END )physical_assets_name,
( SELECT hdft.templet_name FROM hls_doc_file_templet hdft WHERE hdft.templet_id = fpa.template_id ) AS templet_name, ( SELECT hdft.templet_name FROM hls_doc_file_templet hdft WHERE hdft.templet_id = fpa.template_id ) AS template_id_n, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = fpa.bp_id ) AS bp_name, fpa.signing_witness AS signing_witness_name, fpa.witness AS witness_name, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scvb.VALUE = CASE WHEN ( SELECT MAX( fa.creation_date ) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE fa.attachment_id = fam.attachment_id AND fam.table_name = 'CONTRACT_CONTENT' AND fpa.project_attachment_id = fam.table_pk_value ) IS NOT NULL THEN 'N' ELSE 'Y' END AND scb.CODE = 'SYS.YES_NO' AND scvb.code_id = scb.code_id ) AS standard_contract_desc, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scvb. VALUE = fpa.SOURCE_TYPE AND scb.CODE = 'CON.CONTENT_NUM_TYPE' AND scvb.code_id = scb.code_id ) AS SOURCE_TYPE_N FROM fct_project_attachment fpa WHERE 1 = 1 AND fpa.project_id = #{projectId} ORDER BY fpa.document_number asc ) ttt , ( SELECT @rownum := 0 ) r) ttx
1=1
and ttx.project_id = #{projectId}
and ttx.source_type = #{sourceType}
and ttx.status = #{status}
and ttx.bp_category not in ('PRJ_CONTRACT_CONTENT_WFL','FCT_CONTRACT_CONTENT_WFL','PRJ_CONTRACT_CONTENT_ATT','FCT_CONTRACT_CONTENT_ATT')
order by ttx.document_number desc

SELECT fpa.*, ( SELECT su.DESCRIPTION FROM sys_user su WHERE su.USER_ID = fpa.upload_person ) AS upload_person_name, (select tt.DESCRIPTION from hls_bp_type tt where tt.BP_TYPE=fpa.bp_role_type) bp_role_type_n, (select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'FCT_PROJECT_ATTACHMENT' and faam.table_pk_value = fpa.project_attachment_id ) file_name, (select wm_concat(fa.attachment_id) from fnd_atm_attachment fa, fnd_atm_attachment_multi fam where fa.attachment_id = fam.attachment_id and fam.table_name = 'FCT_PROJECT_ATTACHMENT' and fpa.project_attachment_id = fam.table_pk_value) attachment_id, (CASE fpa.content_flag when 'Y' then '已生成' else '未生成' end)content_flag_n, (SELECT su.DESCRIPTION FROM sys_user su WHERE su.USER_ID = fpa.upload_person ) AS upload_person_n, ( select sf.file_id from sys_attachment sa, sys_file sf
fpa.project_attachment_id||''= sa.source_key
AND sa.source_type = #{sourceType}
AND sa.attachment_id = sf.attachment_id and rownum=1
) file_id, ( SELECT hdft.templet_name FROM hls_doc_file_templet hdft WHERE hdft.templet_id = fpa.template_id ) AS template_id_n, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=fpa.bp_id) as bp_id_n, fpa.signing_witness as signing_witness_name, fpa.witness as witness_name, fpa.SYSTEM_NUMBER, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scvb.value=fpa.SOURCE_TYPE and scb.code='CON.CONTENT_NUM_TYPE' and scvb.code_id=scb.code_id ) as SOURCE_TYPE_N FROM fct_project_attachment fpa
1=1
and fpa.project_id = #{projectId}
and fpa.hd_id = #{hdId}
and fpa.source_type = #{sourceType}
and fpa.status = #{status}
and fpa.bp_category not in ('PRJ_CONTRACT_CONTENT_WFL','FCT_CONTRACT_CONTENT_WFL','PRJ_CONTRACT_CONTENT_ATT','FCT_CONTRACT_CONTENT_ATT','CUSTOM_FCT_CONTRACT','CUSTOM_CON_CONTRACT')
order by fpa.creation_date ASC

SELECT fpa.* FROM fct_project_attachment fpa left join HLS_BP_MASTER hm on hm.BP_ID=fpa.BP_ID
AND fpa.project_id = #{projectId}
AND fpa.bp_category like CONCAT('%',CONCAT(#{bpCategory},'%'))
AND fpa.source_type = #{sourceType}
order by fpa.creation_date asc,hm.bp_class desc

SELECT fpa.*, ( SELECT su.DESCRIPTION FROM sys_user su WHERE su.USER_ID = fpa.upload_person ) AS upload_person_name, ( select sf.file_id from sys_attachment sa, sys_file sf
fpa.project_attachment_id||''= sa.source_key
AND sa.source_type = #{sourceType}
AND sa.attachment_id = sf.attachment_id and rownum=1
) file_id, ( SELECT hdft.templet_name FROM hls_doc_file_templet hdft WHERE hdft.templet_id = fpa.template_id ) AS template_id_n, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=fpa.bp_id) as bp_id_n, fpa.signing_witness as signing_witness_name, fpa.witness as witness_name, fpa.SYSTEM_NUMBER, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scvb.value=fpa.SOURCE_TYPE and scb.code='CON.CONTENT_NUM_TYPE' and scvb.code_id=scb.code_id ) as SOURCE_TYPE_N FROM fct_project_attachment fpa
1=1
and fpa.project_id = #{projectId}
and fpa.source_type = #{sourceType}
and fpa.status = #{status}
and fpa.source_id = #{sourceId}
order by fpa.creation_date ASC

select  *   from fct_project_attachment ppb where ppb.TEMPLATE_ID = #{templateId}
and  ppb.project_id=#{projectId}
and  ppb.bp_id=#{bpId}

